const fs = require('fs');
const path = require('path');

async function main() {
  const projectId = process.env.PARAGON_PROJECT_ID;
  const userToken = process.env.PARAGON_USER_TOKEN;

  if (!projectId || !userToken) {
    console.error('Missing PARAGON_PROJECT_ID or PARAGON_USER_TOKEN');
    process.exit(1);
  }

  const url = `https://actionkit.useparagon.com/projects/${projectId}/actions`;

  const body = {
    action: 'MAILGUN_GET_DOMAINS',
    parameters: {} // Assuming no parameters needed for listing domains
  };

  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${userToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(body)
    });

    const data = await response.json();

    if (!response.ok) {
      console.error('Error response:', data);
      // If MAILGUN_GET_DOMAINS is wrong, maybe try another one?
      // But for now, let's just write what we got.
    }

    const outputPath = path.join(__dirname, 'output.json');
    fs.writeFileSync(outputPath, JSON.stringify(data, null, 2));
    console.log(`Output written to ${outputPath}`);
  } catch (error) {
    console.error('Fetch error:', error);
    process.exit(1);
  }
}

main();

